export function getPreloadableFonts(
  nextFontManifest: DeepReadonly<NextFontManifest> | undefined,
  filePath: string | undefined,
  injectedFontPreloadTags: Set<string>
): string[] | null {
  if (!nextFontManifest || !filePath) {
    return null
