  const clonedVaryPath: VaryPath = {
    id: null,
    value: originalVaryPath.value,
    parent: {
      id: '?',
      value: newSearch,
      parent: searchParamsVaryPath.parent,
    },
  }
  return clonedVaryPath as PageVaryPath
