// To distinguish from React error.digest, we use a different symbol here to determine if the error is from console.error or unhandled promise rejection.
const digestSym = Symbol.for('next.console.error.digest')

// Represent non Error shape unhandled promise rejections or console.error errors.
// Those errors will be captured and displayed in Error Overlay.
type ConsoleError = Error & {
  [digestSym]: 'NEXT_CONSOLE_ERROR'
  environmentName: string
}

export function createConsoleError(
  message: string | Error,
  environmentName?: string | null
): ConsoleError {
  const error = (
    typeof message === 'string' ? new Error(message) : message
  ) as ConsoleError
  error[digestSym] = 'NEXT_CONSOLE_ERROR'

  if (environmentName && !error.environmentName) {
    error.environmentName = environmentName
  }

  return error
}

export const isConsoleError = (error: any): error is ConsoleError => {
  return error && error[digestSym] === 'NEXT_CONSOLE_ERROR'
}
import React from 'react'
import isError from '../../../../lib/is-error'

const ownerStacks = new WeakMap<Error, string | null>()

export function getOwnerStack(error: Error): string | null | undefined {
  return ownerStacks.get(error)
}
export function setOwnerStack(error: Error, stack: string | null) {
  ownerStacks.set(error, stack)
}

export function coerceError(value: unknown): Error {
  return isError(value) ? value : new Error('' + value)
}

export function setOwnerStackIfAvailable(error: Error): void {
  // React 18 and prod does not have `captureOwnerStack`
  if ('captureOwnerStack' in React) {
    const ownerStack = React.captureOwnerStack()
    // Only set if we captured a valid owner stack, or if none exists yet.
    // This prevents overwriting a valid owner stack captured earlier
    // (e.g., in onRecoverableError) with null captured later.
    if (ownerStack || !ownerStacks.has(error)) {
      setOwnerStack(error, ownerStack)
    }
  }
}

export function decorateDevError(thrownValue: unknown) {
  const error = coerceError(thrownValue)
  setOwnerStackIfAvailable(error)
  return error
}
const symbolError = Symbol.for('NextjsError')

export function getErrorSource(error: Error): 'server' | 'edge-server' | null {
  return (error as any)[symbolError] || null
}

export type ErrorSourceType = 'edge-server' | 'server'

export function decorateServerError(error: Error, type: ErrorSourceType) {
  Object.defineProperty(error, symbolError, {
    writable: false,
    enumerable: false,
    configurable: false,
    value: type,
  })
}
