    }

    preloadCallbacks?.push(() => {
      ctx.componentMod.preloadStyle(
        fullHref,
        ctx.renderOpts.crossOrigin,
        ctx.nonce
      )
    })

    return createElement('link', {
      key: index,
      rel: 'stylesheet',
      href: fullHref,
      precedence: precedence,
      crossOrigin: ctx.renderOpts.crossOrigin,
      nonce: ctx.nonce,
    })
  })
}
