      const cacheKeyWithoutSearchParams = createRouterCacheKey(segment, true)

      const item = findHeadInCacheImpl(
        childCacheNode,
        childParallelRoutes,
        keyPrefix + '/' + cacheKey,
        keyPrefix + '/' + cacheKeyWithoutSearchParams
      )

      if (item) {
        return item
      }
    }
  }

